/**
 * Find student credentials by register number, email, or short ID (last 5 digits)
 */
export function findStudentCredential(query: string): StudentCredential | undefined {
  if (!query) return undefined;
  const q = query.trim().toLowerCase();
  return STUDENT_CREDENTIALS.find(s => 
    s.registerNumber.toLowerCase() === q ||
    s.email.toLowerCase() === q ||
    s.shortId.toLowerCase() === q ||
    s.studentId.toLowerCase() === q
  );
}

